def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    opp_def = opp_actions.count('D')
    overall_def_rate = opp_def / n

    last_me, last_opp = history[-1]

    # Periodicity check: if opponent's recent moves repeat, defect.
    if n >= 4:
        for p in (2, 3, 4, 5):
            if n >= 2 * p:
                if opp_actions[-p:] == opp_actions[-2*p:-p]:
                    return 'D'

    # Check for exploitation or retaliation.
    exploitable = False
    retaliatory = False
    for i in range(n - 1):
        if my_actions[i] == 'D' and opp_actions[i] == 'C':
            if opp_actions[i+1] == 'C':
                exploitable = True
            elif opp_actions[i+1] == 'D':
                retaliatory = True

    if exploitable:
        if last_opp == 'D':
            return 'C'
        return 'D'

    if retaliatory:
        if last_opp == 'C':
            return 'C'
        else:
            if last_me == 'D':
                if overall_def_rate > 0.7:
                    return 'D'
                return 'C'
            else:
                if overall_def_rate < 0.4:
                    return 'C'
                return 'D'

    # If opponent has never defected, cooperate until we test.
    if opp_def == 0:
        if n >= 10:
            return 'D'
        return 'C'

    # Normal mode with opponent defections.
    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'D':
            if overall_def_rate > 0.7:
                return 'D'
            return 'C'
        else:
            if opp_def <= 1:
                return 'C'
            if overall_def_rate < 0.4:
                return 'C'
            return 'D'
